function asObject(value, fallback = {}) {
  if (!value) return fallback;

  if (typeof value === "object" && !Array.isArray(value)) {
    return value;
  }

  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === "object" ? parsed : fallback;
    } catch {
      return fallback;
    }
  }

  return fallback;
}

const input = $json;

const decision = asObject(input.decision);
const contextPacket = asObject(input.context_packet);
const event = asObject(input.event);
const lead = asObject(input.lead);
const leadState = asObject(input.lead_state);
const meta = asObject(input.meta);

if (!decision.action) {
  throw new Error("Missing decision.action");
}

if (!contextPacket || Object.keys(contextPacket).length === 0) {
  throw new Error("Missing context_packet");
}

return [
  {
    json: {
      ...input,

      event,
      lead,
      lead_state: leadState,
      decision,
      context_packet: contextPacket,

      execution_meta: {
        ...(input.execution_meta || {}),
        execution_id:
          input.execution_meta?.execution_id ||
          Date.now().toString(),
        timestamp: new Date().toISOString(),
        source: "6_action_executor"
      },

      meta: {
        ...meta,
        received_by: "6_action_executor",
        original_action: decision.action
      }
    }
  }
];

const globalAllowedActions = [
  // Flujo base
  "ask_missing_data",
  "send_quote",
  "answer_question",
  "answer_objection",
  "offer_booking",
  "offer_available_slots",
  "confirm_booking",
  "schedule_followup",
  "handoff_human",

  // Prioridad 2 - flujo comercial completo
  "cancel_booking",
  "reschedule_booking",
  "collect_address",
  "confirm_address",
  "send_pre_service_instructions",
  "notify_on_the_way",
  "request_review",
  "request_referral",
  "send_service_menu",
  "recommend_service",
  "ask_payment_preference",
  "check_payment_status"
];

let action = $json.decision?.action;
let contextAllowedActions = $json.context_packet?.allowed_actions;
const errors = [];
function normalizeText(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function isFilled(value) {
  if (value === null || value === undefined) return false;
  if (typeof value === "string" && value.trim() === "") return false;
  return true;
}

function asksRecommendation(rawText) {
  const t = normalizeText(rawText);

  return (
    t.includes("que me recomiendas") ||
    t.includes("que recomiendas") ||
    t.includes("cual me recomiendas") ||
    t.includes("cual me conviene") ||
    t.includes("no se cual elegir") ||
    t.includes("no se que servicio") ||
    t.includes("ayudame a elegir") ||
    t.includes("recomiendame")
  );
}

const state = $json.context_packet?.state || {};

const quoteFailureLock =
  state.last_bot_action === "pricing_rule_not_found" ||
  state.next_goal === "manual_pricing_review";

if (quoteFailureLock && action !== "handoff_human") {
  if (Array.isArray(contextAllowedActions) && !contextAllowedActions.includes("handoff_human")) {
    contextAllowedActions = ["handoff_human", ...contextAllowedActions];
    $json.context_packet = { ...($json.context_packet || {}), allowed_actions: contextAllowedActions };
  }

  action = "handoff_human";

  $json.decision = {
    ...($json.decision || {}),
    action: "handoff_human",
    reason: "action_executor_guard_quote_failure_lock",
    message:
      "No pude calcular la cotización. Te voy a derivar con un asesor para confirmar precio antes de agendar.",
    handoff_reason: $json.decision?.handoff_reason || "quote_pricing_not_available",
    state_update: {
      ...($json.decision?.state_update || {}),
      stage: "human_handoff",
      human_handoff: true,
      next_goal: "manual_pricing_review",
      last_bot_action: "pricing_rule_not_found",
      missing_fields: []
    }
  };
}

const hasCommercialContext =
  isFilled(state.service_interest) &&
  isFilled(state.vehicle_type) &&
  isFilled(state.district);

const latestUserMessage = $json.context_packet?.conversation?.latest_user_message || "";
function userComplaintIntent(rawText) {
  const t = normalizeText(rawText);
  return (
    t.includes("reclamo") ||
    t.includes("reclamar") ||
    t.includes("muy molesto") ||
    t.includes("muy molesta") ||
    t.includes("molesto") ||
    t.includes("molesta") ||
    t.includes("pesimo") ||
    t.includes("pesima") ||
    t.includes("mal servicio") ||
    t.includes("mala experiencia") ||
    t.includes("quiero quejarme") ||
    t.includes("quiero hacer un reclamo") ||
    t.includes("quiero poner un reclamo") ||
    t.includes("necesito soporte")
  );
}

function userReturningCustomerIntent(rawText) {
  const t = normalizeText(rawText);
  const returningSignals =
    t.includes("hace meses") ||
    t.includes("ya lave con ustedes") ||
    t.includes("lave con ustedes") ||
    t.includes("lavado con ustedes") ||
    t.includes("fui cliente") ||
    t.includes("ya fui cliente") ||
    t.includes("otra vez") ||
    t.includes("de nuevo") ||
    t.includes("volver a cotizar") ||
    t.includes("cotizar de nuevo") ||
    t.includes("quiero volver") ||
    t.includes("quiero retomar");

  const commercialIntent =
    t.includes("cotizar") ||
    t.includes("precio") ||
    t.includes("valor") ||
    t.includes("agendar") ||
    t.includes("reserva");

  return returningSignals && commercialIntent;
}

function userExplicitHumanRequest(rawText) {
  const t = normalizeText(rawText);
  return (
    t.includes("hablar con un humano") ||
    t.includes("hablar con una persona") ||
    t.includes("asesor humano") ||
    t.includes("agente humano") ||
    t.includes("derivame con un humano") ||
    t.includes("quiero un humano") ||
    t.includes("necesito un humano") ||
    t.includes("atencion humana")
  );
}

if (userComplaintIntent(latestUserMessage) && state.human_handoff !== true) {
  if (Array.isArray(contextAllowedActions) && !contextAllowedActions.includes("handoff_human")) {
    contextAllowedActions = ["handoff_human", ...contextAllowedActions];
    $json.context_packet = { ...($json.context_packet || {}), allowed_actions: contextAllowedActions };
  }

  action = "answer_question";

  $json.decision = {
    ...($json.decision || {}),
    action: "answer_question",
    reason: "action_executor_guard_customer_complaint_handoff",
    message:
      "Lamento lo ocurrido. Voy a derivarte con una persona del equipo para revisar tu reclamo y ayudarte ahora.",
    handoff_reason: $json.decision?.handoff_reason || "customer_complaint",
    state_update: {
      ...($json.decision?.state_update || {}),
      stage: "human_handoff",
      human_handoff: true,
      intent_last: "customer_complaint",
      next_goal: "human_takeover",
      last_bot_action: "handoff_human",
      missing_fields: []
    }
  };
}

if (userExplicitHumanRequest(latestUserMessage)) {
  if (Array.isArray(contextAllowedActions) && !contextAllowedActions.includes("handoff_human")) {
    contextAllowedActions = ["handoff_human", ...contextAllowedActions];
    $json.context_packet = { ...($json.context_packet || {}), allowed_actions: contextAllowedActions };
  }

  action = "handoff_human";

  $json.decision = {
    ...($json.decision || {}),
    action: "handoff_human",
    reason: "action_executor_guard_explicit_human_request",
    message:
      $json.decision?.message ||
      "Te voy a derivar con una persona para ayudarte mejor.",
    handoff_reason: $json.decision?.handoff_reason || "user_requested_human",
    state_update: {
      ...($json.decision?.state_update || {}),
      stage: "human_handoff",
      human_handoff: true,
      next_goal: "human_takeover",
      last_bot_action: "handoff_human",
      missing_fields: []
    }
  };
}


function userUrgent(rawText) {
  const t = normalizeText(rawText);
  return (
    t.includes("urgente") ||
    t.includes("urgencia") ||
    t.includes("emergencia")
  );
}

if (userUrgent(latestUserMessage) && state.human_handoff !== true) {
  if (Array.isArray(contextAllowedActions) && !contextAllowedActions.includes("handoff_human")) {
    contextAllowedActions = ["handoff_human", ...contextAllowedActions];
    $json.context_packet = { ...($json.context_packet || {}), allowed_actions: contextAllowedActions };
  }

  action = "handoff_human";

  $json.decision = {
    ...($json.decision || {}),
    action: "handoff_human",
    reason: "action_executor_guard_urgent_handoff",
    message:
      $json.decision?.message ||
      "Te voy a derivar con una persona para ayudarte mejor.",
    handoff_reason: $json.decision?.handoff_reason || "urgent_handoff",
    state_update: {
      ...($json.decision?.state_update || {}),
      stage: "human_handoff",
      human_handoff: true,
      next_goal: "human_takeover",
      last_bot_action: "handoff_human",
      missing_fields: []
    }
  };
}
// Handoff lock guard: si ya hay handoff activo, mantener el lock
if (state.human_handoff === true && action && action !== "handoff_human") {
  if (Array.isArray(contextAllowedActions) && !contextAllowedActions.includes("handoff_human")) {
    contextAllowedActions = ["handoff_human", ...contextAllowedActions];
    $json.context_packet = { ...($json.context_packet || {}), allowed_actions: contextAllowedActions };
  }

  action = "handoff_human";

  $json.decision = {
    ...($json.decision || {}),
    action: "handoff_human",
    reason: "action_executor_guard_handoff_lock",
    message:
      $json.decision?.message ||
      "Ya estas siendo atendido por una persona. En breve te responderan.",
    handoff_reason: $json.decision?.handoff_reason || "handoff_lock",
    state_update: {
      ...($json.decision?.state_update || {}),
      stage: "human_handoff",
      human_handoff: true,
      next_goal: "wait_human_response",
      last_bot_action: "human_handoff_already_active",
      missing_fields: []
    }
  };
}

function userPostpones(rawText) {
  const t = normalizeText(rawText);
  return (
    t.includes("despues te aviso") ||
    t.includes("te aviso despues") ||
    t.includes("luego te aviso") ||
    t.includes("mas adelante") ||
    t.includes("otro dia") ||
    t.includes("en otro momento") ||
    t.includes("lo veo y te aviso")
  );
}


if (
  action === "offer_booking" &&
  hasCommercialContext &&
  state.stage === "quoted" &&
  userPostpones(latestUserMessage)
) {
  const scheduledFor = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
if (Array.isArray(contextAllowedActions) && !contextAllowedActions.includes("schedule_followup")) {
  contextAllowedActions = ["schedule_followup", ...contextAllowedActions];
  $json.context_packet = { ...($json.context_packet || {}), allowed_actions: contextAllowedActions };
}
  action = "schedule_followup";

  $json.decision = {
    ...($json.decision || {}),
    action: "schedule_followup",
    reason: "action_executor_guard_postponed_followup_scheduled",
    followup_type: $json.decision?.followup_type || "post_quote_postponed_24h",
    scheduled_for: $json.decision?.scheduled_for || scheduledFor,
    state_update: {
      ...($json.decision?.state_update || {}),
      stage: "closing",
      intent_last: "followup_scheduled",
      next_goal: "wait_followup",
      last_bot_action: "schedule_followup",
    },
  };
}


if (
  userReturningCustomerIntent(latestUserMessage) &&
  action === "ask_missing_data" &&
  !isFilled(state.service_interest) &&
  (isFilled(state.vehicle_type) || isFilled(state.district))
) {
  if (Array.isArray(contextAllowedActions) && !contextAllowedActions.includes("answer_question")) {
    contextAllowedActions = ["answer_question", ...contextAllowedActions];
    $json.context_packet = { ...($json.context_packet || {}), allowed_actions: contextAllowedActions };
  }

  const vehicleText = isFilled(state.vehicle_type) ? " para tu " + String(state.vehicle_type).toLowerCase() : "";
  const districtText = isFilled(state.district) ? " en " + state.district : "";

  action = "answer_question";

  $json.decision = {
    ...($json.decision || {}),
    action: "answer_question",
    reason: "action_executor_guard_returning_customer_collect_service",
    message:
      "Perfecto, retomemos" + vehicleText + districtText + ". Para cotizar, quieres lavado basico, lavado premium o encerado full?",
    state_update: {
      ...($json.decision?.state_update || {}),
      stage: "service_discovery",
      intent_last: "returning_customer_reactivated",
      next_goal: "collect_service_interest",
      last_bot_action: "answer_question",
      missing_fields: ["service_interest"]
    }
  };
}

if (
  action === "recommend_service" &&
  hasCommercialContext &&
  !asksRecommendation(latestUserMessage) &&
  Array.isArray(contextAllowedActions) &&
  contextAllowedActions.includes("send_quote")
) {
  action = "send_quote";

  $json.decision = {
    ...($json.decision || {}),
    action: "send_quote",
    reason: "action_executor_guard_forced_send_quote_because_service_vehicle_district_are_complete",
    state_update: {
      ...($json.decision?.state_update || {}),
      service_interest: state.service_interest,
      vehicle_type: state.vehicle_type,
      district: state.district,
      stage: "qualified",
      next_goal: "send_quote",
      last_bot_action: "send_quote_in_progress",
      missing_fields: []
    }
  };
}

if (!action) {
  errors.push("Missing action");
}

if (action && !globalAllowedActions.includes(action)) {
  errors.push(`Unsupported action: ${action}`);
}

if (!Array.isArray(contextAllowedActions) || contextAllowedActions.length === 0) {
  errors.push("Missing or empty context_packet.allowed_actions");
}

if (
  action &&
  Array.isArray(contextAllowedActions) &&
  contextAllowedActions.length > 0 &&
  !contextAllowedActions.includes(action)
) {
  errors.push(
    `Action not allowed in current state: ${action}. Allowed: ${contextAllowedActions.join(", ")}`
  );
}

if (errors.length > 0) {
  return [{
    error: true,
    errors,
    original: $json
  }];
}

return [{
  ...$json,
  validation: {
    global_action_valid: true,
    context_action_valid: true,
    allowed_actions_checked: contextAllowedActions
  }
}];

const data = $json;
const ctx = data.execution_context || {};

const paymentMode = ctx.payment_mode ||
  (data.context_packet && data.context_packet.state && data.context_packet.state.payment_mode) ||
  (data.context_packet && data.context_packet.agent_business_config &&
   data.context_packet.agent_business_config.config &&
   data.context_packet.agent_business_config.config.payment_mode) ||
  "both";

const isPrepagoreRequired = paymentMode === "prepago_required";

const bookingData = {
  lead_id: ctx.lead_id,
  channel: ctx.channel,
  service_interest: ctx.service_interest,
  vehicle_type: ctx.vehicle_type,
  district: ctx.district,
  booking_date: ctx.booking_date,
  booking_time: ctx.booking_time,
  slot_id: ctx.slot_id,
  availability_confirmed: ctx.availability_confirmed,
  duration_minutes: ctx.duration_minutes || 120,
  calendar_id: ctx.calendar_id || "primary",
  service_address: ctx.service_address || ctx.address || null,
  address_reference: ctx.address_reference || null,
  address_confirmed: ctx.address_confirmed === true
};

if (isPrepagoreRequired) {
  // Skip GCal booking — send payment link first via 6.26
  // GCal event will be created by 6.27 when Flow confirms payment
  const payloadObject = {
    ...data,
    db_operations: ["messages", "lead_state"],
    skip_calendar_booking: true,
    pending_booking_data: bookingData,
    booking_request: bookingData,
    state_update: {
      ...(ctx.state_update || {}),
      last_bot_action: "payment_link_pending",
      payment_mode: "prepago_required",
      payment_preference: "prepago",
      pending_booking_data: bookingData,
    }
  };
  return [{ ...payloadObject, payload: JSON.stringify(payloadObject) }];
}

// Normal booking flow (prepago_only, postpago_only, both)
const payloadObject = {
  ...data,
  db_operations: ["appointments", "messages", "lead_state"],
  booking_request: bookingData,
  state_update: {
    ...(ctx.state_update || {}),
    last_bot_action: "confirm_booking_in_progress"
  }
};

return [{
  ...payloadObject,
  payload: JSON.stringify(payloadObject)
}];

const action =
  $json.execution_context?.action ||
  $json.decision?.action ||
  $json.action ||
  null;
const outcome =
  $json.outcome ||
  $json.execution_result?.outcome ||
  $json.meta?.outcome ||
  null;

const lastBotAction =
  $json.state_update?.last_bot_action ||
  $json.lead_state_update?.last_bot_action ||
  $json.execution_result?.last_bot_action ||
  null;

const bot =
  $json.message ||
  $json.message_to_send ||
  $json.meta?.bot ||
  null;

const messageSent = $json.message_sent === true;

const toolRegistry =
  $json.meta?.tool_registry ||
  $json.tool_registry ||
  null;

const audit = {
  audit_id: $json.audit_id || null,
  flow_name: $json.flow_name || "action_executor",
  decision: $json.audit_decision || $json.decision || null,
  idempotency_key:
    $json.idempotency_key ||
    $json.execution_context?.idempotency_key ||
    null,
  inbound_message_id:
    $json.inbound_message_id ||
    $json.execution_context?.inbound_message_id ||
    null,
  outbound_message_id:
    $json.outbound_message_id ||
    null,
  tool_name:
    $json.tool_name ||
    $json.execution_context?.tool_name ||
    $json.meta?.tool_name ||
    $json.meta?.tool_registry?.tool_name ||
    $json.tool_registry?.tool_name ||
    (Array.isArray($json.meta?.tool_registry?.mapped_tool_names) ? $json.meta.tool_registry.mapped_tool_names[0] : null) ||
    (Array.isArray($json.tool_registry?.mapped_tool_names) ? $json.tool_registry.mapped_tool_names[0] : null) ||
    null,
  executor_ref:
    $json.executor_ref ||
    $json.execution_context?.executor_ref ||
    $json.meta?.executor_ref ||
    null,
  agent_id:
    $json.agent_id ||
    $json.execution_context?.agent_id ||
    $json.meta?.agent_id ||
    null,
  tool_registry: toolRegistry
};

const qaFailedReasons = [];

if (!bot) qaFailedReasons.push("bot_null");
if (messageSent !== true) qaFailedReasons.push("message_sent_not_true");
if (!audit.flow_name) qaFailedReasons.push("flow_name_null");
if (!audit.decision) qaFailedReasons.push("decision_null");
if (!audit.idempotency_key) qaFailedReasons.push("idempotency_key_null");
if (!audit.audit_id && $json.message_sent === true) {
  qaFailedReasons.push("audit_not_inserted");
}

if (!audit.inbound_message_id) {
  qaFailedReasons.push("inbound_message_id_null");
}

if (!audit.outbound_message_id && $json.outbound_message_saved === true) {
  qaFailedReasons.push("audit_outbound_message_id_null");
}
if ($json.outbound_message_saved !== true && bot) {
  qaFailedReasons.push("outbound_message_not_saved");
}
const isHandoff = action === "handoff_human";

const handoffResult = {
  human_handoff:
    $json.state_update?.human_handoff === true ||
    $json.lead_state_update?.human_handoff === true ||
    $json.handoff === true,

  handoff_case_id:
    $json.handoff_case_id ||
    $json.meta?.handoff?.handoff_case_id ||
    null,

  assigned_to:
    $json.assigned_to ||
    $json.meta?.handoff?.assigned_to ||
    null,

  assigned_team:
    $json.assigned_team ||
    $json.meta?.handoff?.assigned_team ||
    null,

  notification_sent:
    $json.notification_sent === true ||
    $json.meta?.handoff?.notification_sent === true
};

if (isHandoff) {
  if (handoffResult.human_handoff !== true) {
    qaFailedReasons.push("handoff_human_not_true");
  }

  if (!handoffResult.handoff_case_id) {
    qaFailedReasons.push("handoff_case_id_null");
  }

  if (!handoffResult.assigned_to) {
    qaFailedReasons.push("assigned_to_null");
  }

  if (!handoffResult.assigned_team) {
    qaFailedReasons.push("assigned_team_null");
  }

  if (handoffResult.notification_sent !== true) {
    qaFailedReasons.push("notification_sent_not_true");
  }
}
const proposedStateUpdate =
  $json.proposed_state_update ||
  $json.decision?.state_update ||
  {};
const sanitizedStateUpdate =
  $json.sanitized_state_update ||
  $json.state_update ||
  {};

function normalizeCompareValue(value) {
  if (value === undefined) return "__undefined__";
  if (value === null) return null;

  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }

  if (Array.isArray(value)) {
    return JSON.stringify(value);
  }

  if (typeof value === "boolean") {
    return value;
  }

  return value;
}

function valuesMatch(expected, actual) {
  const e = normalizeCompareValue(expected);
  const a = normalizeCompareValue(actual);

  if (e === "__undefined__") return true;

  if (typeof e === "boolean") {
    return a === e || String(a).toLowerCase() === String(e);
  }

  return JSON.stringify(e) === JSON.stringify(a);
}

const persistedStateCurrent =
  $json.persisted_state_current ||
  $json.state?.current ||
  null;

const stateMismatchFields = [];



if ($json.state_updated === true && persistedStateCurrent) {
  const keysToCompare = [
    "stage",
    "intent_last",
    "service_interest",
    "vehicle_type",
    "district",

    "mentioned_vehicle_type",
    "confirmed_vehicle_type",
    "mentioned_district",
    "confirmed_district",

    "last_bot_action",
    "next_goal",
    "human_handoff",
    "booking_date",
    "booking_time",
    "slot_id",
    "availability_confirmed",
    "service_address",
    "address_reference",
    "address_confirmed",
    "cancellation_reason",
    "reschedule_reason",
    "last_appointment_event_id"
  ];

  for (const key of keysToCompare) {
    if (sanitizedStateUpdate[key] === undefined) continue;

  if (!valuesMatch(sanitizedStateUpdate[key], persistedStateCurrent[key])) {
  stateMismatchFields.push({
    field: key,
    expected: sanitizedStateUpdate[key],
    actual: persistedStateCurrent[key],
  });
}
}
}

if (stateMismatchFields.length > 0) {
  qaFailedReasons.push(
    "state_current_does_not_match_sanitized_state_update:" +
    JSON.stringify(stateMismatchFields)
  );
}
if ($json.state_updated === true && !persistedStateCurrent) {
  qaFailedReasons.push("state_current_missing_after_update");
}

return [{
  execution_result: {
    success: qaFailedReasons.length === 0,
    action,
    outcome,
    last_bot_action: lastBotAction,
    bot,
    message_sent: messageSent,
    message_saved: $json.outbound_message_saved === true,
    outbound_message_id: $json.outbound_message_id || null,
    state_updated: $json.state_updated === true,
    state: {
  proposed_update: proposedStateUpdate,
  sanitized_update: sanitizedStateUpdate,
  current: persistedStateCurrent,
  mismatch_fields: stateMismatchFields,
},

    handoff: isHandoff ? handoffResult : null,

    audit,
    tool_registry: toolRegistry,
    qa: {
      passed: qaFailedReasons.length === 0,
      failed_reasons: qaFailedReasons
    },
    db_records_created: $json.records || $json.db_operations || [],
    notes: $json.notes || []
  }
}];

