    service_interest: fv(pending.service_interest, ctx.service_interest, state.service_interest),
    vehicle_type: fv(pending.vehicle_type, ctx.vehicle_type, state.vehicle_type),
    district: fv(pending.district, ctx.district, state.district),
    booking_date: bookingDate, booking_time: bookingTime,
    slot_id: fv(pending.slot_id, ctx.slot_id),
    calendar_id: fv(pending.calendar_id, ctx.calendar_id),
    duration_minutes: fv(pending.duration_minutes, ctx.duration_minutes) || 120,
    service_address: fv(pending.service_address, ctx.service_address, ctx.address),
    quoted_price: fv(ctx.quoted_price, state.quoted_price),
    payment_mode: "prepago_required", payment_preference: "prepago",
    state_update: { ...(data.state_update || {}), pending_booking_data: pending,
      payment_mode: "prepago_required", payment_preference: "prepago", last_bot_action: "payment_link_pending" }
  },
  db_operations: ["messages", "lead_state"]
};
return [{ ...payloadObject, payload: JSON.stringify(payloadObject) }];

// 6.5 returns items from parallel terminal nodes (booking result + DB followup records).
// Find the item with execution_result (the actual booking confirmation result).
const allItems = $input.all();
if (!allItems || allItems.length === 0) {
  return [{ json: { payment_preference_direct: '' } }];
}

const bookingResult = allItems.find(i => i.json && i.json.execution_result != null) || allItems[0];

// Collect payment_preference from all items
let paymentPref = '';
for (const item of allItems) {
  if (!item.json) continue;
  const j = item.json;
  const pref =
    j.payment_preference_direct ||
    (j.context_packet && j.context_packet.state && j.context_packet.state.payment_preference) ||
    (j.execution_context && j.execution_context.payment_preference) ||
    (j.state_update && j.state_update.payment_preference) ||
    '';
  if (pref) { paymentPref = pref; break; }
}

// Also check bookingResult specifically (redundant but explicit)
if (!paymentPref && bookingResult && bookingResult.json) {
  const j = bookingResult.json;
  paymentPref =
    j.payment_preference_direct ||
    (j.context_packet && j.context_packet.state && j.context_packet.state.payment_preference) ||
    (j.execution_context && j.execution_context.payment_preference) ||
    '';
}

const resultJson = bookingResult && bookingResult.json ? bookingResult.json : {};
return [{ json: { ...resultJson, payment_preference_direct: paymentPref } }];

// message_to_send is lost after inser_quote (Postgres INSERT returns only DB row).
// Recover full context from Call '6.8 send_quote' output.
// 6.8 output includes message_to_send and a partial state_update (quoted_price, etc.)
// but NOT the full state_update from rules_engine (which has stage=qualified, last_bot_action).
// Merge both state_updates to preserve all fields.
const quoteCtx = $("Call '6.8 send_quote'").first()?.json || {};
const rulesStateUpdate = quoteCtx.decision?.state_update || {};
const quoteStateUpdate = quoteCtx.state_update || {};
return [{
  json: {
    ...quoteCtx,
    state_update: {
      ...rulesStateUpdate,
      ...quoteStateUpdate
    },
    offers_or_quotes_id: $json.id || null
  }
}];
